var Scrapyard=Scrapyard||{};Scrapyard.UIPreloadState=Classy.newClass();Scrapyard.UIPreloadState.methods({preload:function(){if(this.game.device.pixelRatio>1){this.load.spritesheet('plates',g_url('assets/images/snippets/plates@2x.png'),22,42,20);}else{this.load.spritesheet('plates',g_url('assets/images/snippets/plates.png'),11,21,20);}},create:function(){this.state.start('Main');}});